package it.hurts.sskirillss.relics.entities;

import it.hurts.octostudios.octolib.module.particle.trail.EntityTrailProvider;
import it.hurts.sskirillss.relics.init.RelicsItems;
import it.hurts.sskirillss.relics.items.relics.head.PiglinMaskItem;
import it.hurts.sskirillss.relics.utils.EntityUtils;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.MoverType;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.api.distmarker.OnlyIn;
import net.neoforged.neoforge.fluids.FluidType;

import java.util.List;

public class GoldenToothEntity extends Entity {
    private static final EntityDataAccessor<Integer> STACKS = SynchedEntityData.defineId(GoldenToothEntity.class, EntityDataSerializers.INT);

    public GoldenToothEntity(EntityType<? extends GoldenToothEntity> type, Level level) {
        super(type, level);
    }

    public int getStacks() {
        return this.getEntityData().get(GoldenToothEntity.STACKS);
    }

    public void setStacks(int experience) {
        this.getEntityData().set(GoldenToothEntity.STACKS, experience);
    }

    private List<ItemStack> getSuitableRelics(LivingEntity entity) {
        return EntityUtils.findEquippedCurios(entity, RelicsItems.PIGLIN_MASK.get());
    }

    @Override
    public void tick() {
        super.tick();

        if (!this.isNoGravity())
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.03D, 0.0D));

        if (!this.level().noCollision(this.getBoundingBox()))
            this.moveTowardsClosestSpace(this.getX(), (this.getBoundingBox().minY + this.getBoundingBox().maxY) / 2.0D, this.getZ());

        if (this.tickCount >= 15) {
            for (var tooth : this.level().getEntitiesOfClass(GoldenToothEntity.class, this.getBoundingBox())) {
                if (tooth.getUUID().equals(this.getUUID()) || tooth.isRemoved())
                    continue;

                this.setStacks(this.getStacks() + tooth.getStacks());

                tooth.discard();
            }

            double maxDistance = 16;

            var player = this.level().getNearestPlayer(this.getX(), this.getY(), this.getZ(), maxDistance, entity -> {
                var entry = (Player) entity;

                return !entry.isSpectator() && !this.getSuitableRelics(entry).isEmpty();
            });

            if (player != null) {
                this.setDeltaMovement(this.getDeltaMovement().add(player.position().add(0F, player.getBbHeight() / 2F, 0F).subtract(this.position()).normalize().scale((maxDistance - this.position().distanceTo(player.position())) / (maxDistance * 10))));

                if (this.position().distanceTo(player.position()) <= player.getBbWidth() * 1.25F) {
                    var suitable = this.getSuitableRelics(player);

                    for (var stack : suitable) {
                        var relic = ((PiglinMaskItem) stack.getItem());

                        if (relic.getStacks(stack) < PiglinMaskItem.getMaxStacks()) {
                            relic.addStacks(stack, this.getStacks());
                            relic.setDuration(player, stack, relic.getMaxDuration(player, stack));

                            relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("looting").getStatisticData().getMetricData("teeth_picked_up").addValue(this.getStacks());
                            relic.getRelicData(player, stack).getLevelingData().addExperience("looting", "stack", this.getStacks());
                        }

                        player.addItem(new ItemStack(RelicsItems.GOLDEN_TOOTH.get(), this.getStacks()));

                        this.discard();

                        this.level().playSound(null, this.blockPosition(), SoundEvents.ARMOR_EQUIP_GOLD.value(), SoundSource.MASTER, 0.5F, 1.25F + this.level().getRandom().nextFloat() * 0.75F);
                    }
                }
            }
        }

        this.move(MoverType.SELF, this.getDeltaMovement());

        var friction = 0.98F;

        if (this.onGround()) {
            var pos = getBlockPosBelowThatAffectsMyMovement();

            friction = this.level().getBlockState(pos).getFriction(this.level(), pos, this) * 0.98F;
        }

        this.setDeltaMovement(this.getDeltaMovement().multiply(friction, 0.98D, friction));

        if (this.onGround())
            this.setDeltaMovement(this.getDeltaMovement().multiply(1D, -0.9D, 1D));

        if (this.tickCount >= 1000)
            this.discard();
    }

    @Override
    protected void readAdditionalSaveData(CompoundTag tag) {
        this.setStacks(tag.getInt("stacks"));
    }

    @Override
    protected void addAdditionalSaveData(CompoundTag tag) {
        tag.putInt("stacks", this.getStacks());
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        builder.define(STACKS, 0);
    }

    @Override
    public BlockPos getBlockPosBelowThatAffectsMyMovement() {
        return this.getOnPos(0.999F);
    }

    @Override
    protected MovementEmission getMovementEmission() {
        return MovementEmission.NONE;
    }

    @Override
    public boolean isAttackable() {
        return false;
    }

    @Override
    public SoundSource getSoundSource() {
        return SoundSource.AMBIENT;
    }

    @Override
    public boolean isPushedByFluid(FluidType type) {
        return false;
    }

    @Override
    public void onSyncedDataUpdated(EntityDataAccessor<?> pKey) {
        if (GoldenToothEntity.STACKS.equals(pKey))
            this.refreshDimensions();

        super.onSyncedDataUpdated(pKey);
    }

    @OnlyIn(Dist.CLIENT)
    public static class TrailProvider extends EntityTrailProvider<GoldenToothEntity> {
        public TrailProvider(GoldenToothEntity entity) {
            super(entity);
        }

        @Override
        public Vec3 getTrailPosition(float partialTicks) {
            return this.entity.getPosition(partialTicks).add(0F, 0.45F, 0F);
        }

        @Override
        public int getTrailUpdateFrequency() {
            return 1;
        }

        @Override
        public boolean isTrailAlive() {
            return this.entity.isAlive();
        }

        @Override
        public boolean isTrailGrowing() {
            return this.entity.tickCount > 1;
        }

        @Override
        public int getTrailMaxLength() {
            return 3;
        }

        @Override
        public int getTrailFadeInColor() {
            return 0xFFFFFF00;
        }

        @Override
        public int getTrailFadeOutColor() {
            return 0x00FF0000;
        }

        @Override
        public double getTrailScale() {
            return 0.1F;
        }
    }
}

package it.hurts.sskirillss.relics.entities;

import it.hurts.sskirillss.relics.api.relic_containers.RelicContainer;
import it.hurts.sskirillss.relics.api.relics.IRelicItem;
import it.hurts.sskirillss.relics.init.RelicsRegistries;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.neoforged.neoforge.fluids.FluidType;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class RelicExperienceOrbEntity extends Entity {
    private static final EntityDataAccessor<Integer> EXPERIENCE = SynchedEntityData.defineId(RelicExperienceOrbEntity.class, EntityDataSerializers.INT);

    public RelicExperienceOrbEntity(EntityType<? extends RelicExperienceOrbEntity> type, Level level) {
        super(type, level);
    }

    public static int getMaxExperience() {
        return 10;
    }

    public int getExperience() {
        return this.getEntityData().get(EXPERIENCE);
    }

    public void setExperience(int experience) {
        this.getEntityData().set(EXPERIENCE, experience);
    }

    public int getStage() {
        int stages = 5;

        return Mth.clamp(getExperience() <= 1 ? 1 : Math.min((getExperience() / (getMaxExperience() / Math.max(1, stages - 1))) + 1, stages), 1, stages);
    }

    private List<ItemStack> getUpgradeableRelics(Player player) {
        List<ItemStack> relics = new ArrayList<>();

        for (RelicContainer source : RelicsRegistries.RELIC_CONTAINER_REGISTRY.entrySet().stream().map(Map.Entry::getValue).toList())
            relics.addAll(source.gatherRelics().apply(player).stream().filter(entry -> !((IRelicItem) entry.getItem()).getRelicData(player, entry).isMaxLevel()).toList());

        return relics;
    }

    @Override
    public void tick() {
        super.tick();

        if (!this.isNoGravity())
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.03D, 0.0D));

        if (!this.level().noCollision(this.getBoundingBox()))
            this.moveTowardsClosestSpace(this.getX(), (this.getBoundingBox().minY + this.getBoundingBox().maxY) / 2.0D, this.getZ());

        if (this.tickCount >= 15) {
            if (this.getExperience() < getMaxExperience()) {
                for (RelicExperienceOrbEntity orb : this.level().getEntitiesOfClass(RelicExperienceOrbEntity.class, this.getBoundingBox())) {
                    if (orb.getUUID().equals(this.getUUID()) || orb.isRemoved() || orb.getExperience() >= getMaxExperience())
                        continue;

                    int diff = getMaxExperience() - this.getExperience();

                    if (orb.getExperience() < diff) {
                        this.setExperience(this.getExperience() + orb.getExperience());

                        orb.discard();
                    } else {
                        orb.setExperience(orb.getExperience() - diff);

                        this.setExperience(getMaxExperience());
                    }
                }
            }

            double maxDistance = 16;

            Player player = this.level().getNearestPlayer(this.getX(), this.getY(), this.getZ(), maxDistance, entity -> {
                Player entry = (Player) entity;

                return !entry.isSpectator() && !getUpgradeableRelics(entry).isEmpty();
            });

            if (player != null) {
                this.setDeltaMovement(this.getDeltaMovement().add(player.position().add(0F, player.getBbHeight() / 2F, 0F).subtract(this.position()).normalize().scale((maxDistance - this.position().distanceTo(player.position())) / (maxDistance * 10))));

                if (this.position().distanceTo(player.position()) <= player.getBbWidth() * 1.25F) {
                    List<ItemStack> upgradeable = getUpgradeableRelics(player);

                    if (!upgradeable.isEmpty()) {
                        ItemStack stack = upgradeable.get(random.nextInt(upgradeable.size()));
                        IRelicItem relic = (IRelicItem) stack.getItem();

                        var isMaxLevel = relic.getRelicData(player, stack).isMaxLevel();

                        var toSpread = isMaxLevel ? 0 : this.getExperience() * 0.25D;

                        if (!isMaxLevel)
                            relic.getRelicData(player, stack).getLevelingData().addExperience(this.getExperience());

                        if (toSpread > 0) {
                            var relics = RelicsRegistries.RELIC_CONTAINER_REGISTRY.entrySet().stream()
                                    .map(Map.Entry::getValue)
                                    .flatMap(source -> source.gatherRelics().apply(player).stream())
                                    .filter(entry -> entry.getItem() instanceof IRelicItem relicItem
                                            && !relicItem.getRelicData(player, entry).isMaxLevel()
                                            && !stack.equals(entry))
                                    .toList();

                            if (!relics.isEmpty()) {
                                var relicStack = relics.get(player.level().getRandom().nextInt(relics.size()));

                                if (relicStack.getItem() instanceof IRelicItem relicItem)
                                    relicItem.getRelicData(player, relicStack).getLevelingData().addExperience(toSpread);
                            }
                        }

                        this.discard();

                        this.level().playSound(null, this.blockPosition(), SoundEvents.EXPERIENCE_ORB_PICKUP, SoundSource.MASTER, 0.5F, 1.25F + this.level().getRandom().nextFloat() * 0.75F);
                    }
                }
            }
        }

        this.move(MoverType.SELF, this.getDeltaMovement());

        float friction = 0.98F;

        if (this.onGround()) {
            BlockPos pos = getBlockPosBelowThatAffectsMyMovement();

            friction = this.level().getBlockState(pos).getFriction(this.level(), pos, this) * 0.98F;
        }

        this.setDeltaMovement(this.getDeltaMovement().multiply(friction, 0.98D, friction));

        if (this.onGround())
            this.setDeltaMovement(this.getDeltaMovement().multiply(1.0D, -0.9D, 1.0D));

        if (this.tickCount >= 1000)
            this.discard();
    }

    @Override
    protected void readAdditionalSaveData(CompoundTag tag) {
        setExperience(tag.getInt("experience"));
    }

    @Override
    protected void addAdditionalSaveData(CompoundTag tag) {
        tag.putInt("experience", getExperience());
    }

    @Override
    protected void defineSynchedData(SynchedEntityData.Builder builder) {
        builder.define(EXPERIENCE, 0);
    }

    @Override
    public BlockPos getBlockPosBelowThatAffectsMyMovement() {
        return this.getOnPos(0.999F);
    }

    @Override
    protected MovementEmission getMovementEmission() {
        return MovementEmission.NONE;
    }

    @Override
    public boolean isAttackable() {
        return false;
    }

    @Override
    public SoundSource getSoundSource() {
        return SoundSource.AMBIENT;
    }

    @Override
    public boolean isPushedByFluid(FluidType type) {
        return false;
    }

    @Override
    public void onSyncedDataUpdated(EntityDataAccessor<?> pKey) {
        if (EXPERIENCE.equals(pKey))
            this.refreshDimensions();

        super.onSyncedDataUpdated(pKey);
    }

    @Override
    public EntityDimensions getDimensions(Pose pPose) {
        float scale = 0.15F + (getStage() * 0.05F);

        return EntityDimensions.scalable(scale, scale);
    }

    @Override
    public boolean shouldRenderAtSqrDistance(double pDistance) {
        double d0 = this.getBoundingBox().inflate(0.2F).getSize();

        if (Double.isNaN(d0))
            d0 = 1D;

        d0 *= 64D;

        return pDistance < d0 * d0;
    }
}

package com.aetherteam.aether.event.listeners;

import com.aetherteam.aether.Aether;
import com.aetherteam.aether.event.hooks.EntityHooks;
import io.wispforest.accessories.api.AccessoriesAPI;
import io.wispforest.accessories.api.AccessoriesCapability;
import io.wispforest.accessories.api.Accessory;
import io.wispforest.accessories.api.events.OnDeathCallback;
import net.fabricmc.fabric.api.util.TriState;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LightningBolt;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.enchantment.EnchantmentHelper;
import net.minecraft.world.item.enchantment.Enchantments;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.event.entity.EntityJoinLevelEvent;
import net.neoforged.neoforge.event.entity.EntityMountEvent;
import net.neoforged.neoforge.event.entity.EntityStruckByLightningEvent;
import net.neoforged.neoforge.event.entity.ProjectileImpactEvent;
import net.neoforged.neoforge.event.entity.living.*;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;
import net.neoforged.neoforge.event.tick.PlayerTickEvent;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Optional;

public class EntityListener {
    /**
     * @see Aether#eventSetup(IEventBus)
     */
    public static void listen(IEventBus bus) {
        bus.addListener(EntityListener::onEntityJoin);
        bus.addListener(EntityListener::onMountEntity);
        bus.addListener(EntityListener::onRiderTick);
        bus.addListener(EntityListener::onInteractWithEntity);
        bus.addListener(EntityListener::onProjectileHitEntity);
        bus.addListener(EntityListener::onShieldBlock);
        bus.addListener(EntityListener::onLightningStrike);
        bus.addListener(EntityListener::onPlayerDrops);
        bus.addListener(EntityListener::onDropExperience);
        bus.addListener(EntityListener::onEffectApply);
        bus.addListener(EntityListener::onEntitySplit);
        bus.addListener(EntityListener::onLoadPlayerFile);

        OnDeathCallback.EVENT.register((currentState, entity, capability, damageSource, droppedStacks) -> {
            List<ItemStack> droppedStacksCopy = new ArrayList<>(droppedStacks);
            boolean recentlyHit = entity.hurtMarked;
            int looting = EnchantmentHelper.getEnchantmentLevel(entity.level().registryAccess().holderOrThrow(Enchantments.LOOTING), entity);
            droppedStacks.clear();
            droppedStacks.addAll(EntityHooks.handleEntityAccessoryDrops(entity, droppedStacksCopy, recentlyHit, looting));
            return TriState.DEFAULT;
        });
    }

    /**
     * @see EntityHooks#addGoals(Entity)
     * @see EntityHooks#canMobSpawnWithAccessories(Entity)
     */
    public static void onEntityJoin(EntityJoinLevelEvent event) {
        Entity entity = event.getEntity();
        EntityHooks.addGoals(entity);
    }

    /**
     * @see EntityHooks#dismountPrevention(Entity, Entity, boolean)
     */
    public static void onMountEntity(EntityMountEvent event) {
        Entity riderEntity = event.getEntityMounting();
        Entity mountEntity = event.getEntityBeingMounted();
        boolean isDismounting = event.isDismounting();
        if (EntityHooks.dismountPrevention(riderEntity, mountEntity, isDismounting)) {
            event.setCanceled(true);
        } else {
            EntityHooks.trackMount(mountEntity, isDismounting);
        }
    }

    /**
     * @see EntityHooks#launchMount(Player)
     */
    public static void onRiderTick(PlayerTickEvent.Post event) {
        Player player = event.getEntity();
        EntityHooks.launchMount(player);
    }

    /**
     * @see EntityHooks#skyrootBucketMilking(Entity, Player, InteractionHand)
     * @see EntityHooks#pickupBucketable(Entity, Player, InteractionHand)
     * @see EntityHooks#interactWithArmorStand(Entity, Player, ItemStack, Vec3, InteractionHand)
     */
    public static void onInteractWithEntity(PlayerInteractEvent.EntityInteractSpecific event) {
        Entity targetEntity = event.getTarget();
        Player player = event.getEntity();
        ItemStack itemStack = event.getItemStack();
        Vec3 position = event.getLocalPos();
        InteractionHand interactionHand = event.getHand();
        EntityHooks.skyrootBucketMilking(targetEntity, player, interactionHand);
        Optional<InteractionResult> result = EntityHooks.pickupBucketable(targetEntity, player, interactionHand);
        if (result.isEmpty()) {
            result = EntityHooks.interactWithArmorStand(targetEntity, player, itemStack, position, interactionHand);
        }
        result.ifPresent(event::setCancellationResult);
        event.setCanceled(result.isPresent());
    }

    /**
     * @see EntityHooks#preventEntityHooked(Entity, HitResult)
     */
    public static void onProjectileHitEntity(ProjectileImpactEvent event) {
        Entity projectileEntity = event.getEntity();
        HitResult rayTraceResult = event.getRayTraceResult();
        if (EntityHooks.preventEntityHooked(projectileEntity, rayTraceResult)) event.setCanceled(true);
    }

    /**
     * @see EntityHooks#preventSliderShieldBlock(DamageSource)
     */
    public static void onShieldBlock(LivingShieldBlockEvent event) {
        if (!event.isCanceled()) {
            event.setCanceled(EntityHooks.preventSliderShieldBlock(event.getDamageSource()));
        }
    }

    /**
     * @see EntityHooks#lightningHitKeys(Entity)
     */
    public static void onLightningStrike(EntityStruckByLightningEvent event) {
        Entity entity = event.getEntity();
        LightningBolt lightningBolt = event.getLightning();
        if (EntityHooks.lightningHitKeys(entity) || EntityHooks.thunderCrystalHitItems(entity, lightningBolt)) {
            event.setCanceled(true);
        }
    }

    /**
     * @see EntityHooks#trackDrops(LivingEntity, Collection)
     */
    public static void onPlayerDrops(LivingDropsEvent event) {
        LivingEntity entity = event.getEntity();
        Collection<ItemEntity> itemDrops = event.getDrops();
        EntityHooks.trackDrops(entity, itemDrops);
    }

    /**
     * @see EntityHooks#modifyExperience(LivingEntity, int)
     */
    public static void onDropExperience(LivingExperienceDropEvent event) {
        LivingEntity livingEntity = event.getEntity();
        int experience = event.getDroppedExperience();
        int newExperience = EntityHooks.modifyExperience(livingEntity, experience);
        event.setDroppedExperience(newExperience);
    }

    /**
     * @see EntityHooks#preventInebriation(LivingEntity, MobEffectInstance)
     */
    public static void onEffectApply(MobEffectEvent.Applicable event) {
        LivingEntity livingEntity = event.getEntity();
        MobEffectInstance effectInstance = event.getEffectInstance();
        if (EntityHooks.preventInebriation(livingEntity, effectInstance)) {
            event.setResult(MobEffectEvent.Applicable.Result.DO_NOT_APPLY);
        }
    }

    /**
     * @see EntityHooks#preventSplit(Mob)
     */
    public static void onEntitySplit(MobSplitEvent event) {
        Mob mob = event.getParent();
        if (EntityHooks.preventSplit(mob)) {
            event.setCanceled(true);
        }
    }

    public static void onLoadPlayerFile(PlayerEvent.LoadFromFile event) {
        Player player = event.getEntity();
        if (player instanceof ServerPlayer serverPlayer) {
            CompoundTag playerTag = serverPlayer.server.getWorldData().getLoadedPlayerTag();
            if (playerTag == null) return;

            var capsTag = tryGetCapsTag(playerTag);
            if (capsTag.isEmpty()) return;

            CompoundTag curiosInventoryTag = capsTag.get().getCompound("curios:inventory");
            if (curiosInventoryTag.getBoolean("AccessoriesEncoded") || !curiosInventoryTag.contains("Curios")) return;

            Tag curiosTag = curiosInventoryTag.get("Curios");
            if (curiosTag instanceof ListTag curiosListTag) {
                for (Tag tag : curiosListTag) {
                    if (tag instanceof CompoundTag compoundTag && compoundTag.contains("StacksHandler") && compoundTag.contains("Identifier")) {
                        CompoundTag stacksHandlerTag = compoundTag.getCompound("StacksHandler");
                        if (!stacksHandlerTag.contains("Stacks")) continue;

                        CompoundTag stacksTag = stacksHandlerTag.getCompound("Stacks");
                        if (!stacksTag.contains("Items")) continue;

                        Tag itemsTag = stacksTag.get("Items");
                        if (itemsTag instanceof ListTag listTag) {
                            for (Tag itemTag : listTag) {
                                if (itemTag instanceof CompoundTag itemCompoundTag) {
                                    if (!itemCompoundTag.contains("id")) continue;

                                    var location = ResourceLocation.parse(itemCompoundTag.getString("id"));
                                    if (!location.getNamespace().equals(Aether.MODID)) continue;

                                    Item item = BuiltInRegistries.ITEM.get(location);
                                    if (item == Items.AIR) continue;

                                    ItemStack stack = new ItemStack(item);
                                    AccessoriesCapability accessories = AccessoriesCapability.get(player);
                                    if (accessories == null) continue;

                                    Accessory accessory = AccessoriesAPI.getOrDefaultAccessory(stack);
                                    var equipReference = accessories.canEquipAccessory(stack, true);
                                    if (equipReference == null) continue;

                                    if (accessory.canEquip(stack, equipReference.first())) {
                                        equipReference.second().equipStack(stack.copy());
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private static Optional<CompoundTag> tryGetCapsTag(CompoundTag playerTag) {
        if (playerTag == null) return Optional.empty();

        CompoundTag capsTag = null;
        if (playerTag.contains("ForgeCaps")) {
            capsTag = playerTag.getCompound("ForgeCaps");
        } else if (playerTag.contains("neoforge:attachments")) {
            capsTag = playerTag.getCompound("neoforge:attachments");
        } else {
            return Optional.empty();
        }

        return capsTag.contains("curios:inventory")
            ? Optional.of(capsTag)
            : Optional.empty();
    }
}

